inlines.value:
server {
  listen       80;
  server_name  _;
  root         /srv/www;

  location = /.etc/nginx/rewrite.conf {
    deny    all;
    return  404;
  }

  include /srv/www/.etc/nginx/rewrite.conf;

  location / {
      index  index.html;
      # uncomment the next line if using --html-url-extension-style drop
      #try_files $uri $uri.html $uri/index.html = 404;
  }

  error_page  404  /404.html;
}
